17	package org.springframework.samples.petclinic.rest;
18	
19	import java.io.IOException;
20	import java.util.Map;
21	import java.util.concurrent.ConcurrentHashMap;
22	
23	import org.springframework.stereotype.Component;
24	import org.springframework.web.filter.OncePerRequestFilter;
25	import org.springframework.web.util.ContentCachingResponseWrapper;
26	
27	import jakarta.servlet.FilterChain;
28	import jakarta.servlet.ServletException;
29	import jakarta.servlet.http.HttpServletRequest;
30	import jakarta.servlet.http.HttpServletResponse;
31	
32	/**
33	 * Makes {@code POST /api/owners} idempotent per {@code Idempotency-Key} header: a repeat
34	 * carrying an already-seen key replays the original create's body with status 200 instead
35	 * of creating a duplicate. Kept as a standalone filter so the create endpoint stays
36	 * untouched.
37	 */
38	@Component
39	public class IdempotentOwnerCreateFilter extends OncePerRequestFilter {
40	
41	    private final Map<String, byte[]> responsesByKey = new ConcurrentHashMap<>();
42	
43	    @Override
44	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
45	                                    FilterChain chain) throws ServletException, IOException {
46	        String key = request.getHeader("Idempotency-Key");
47	        if (key == null || !"POST".equalsIgnoreCase(request.getMethod())
48	                || !request.getRequestURI().endsWith("/api/owners")) {
49	            chain.doFilter(request, response);
50	            return;
51	        }
52	        byte[] original = responsesByKey.get(key);
53	        if (original != null) {
54	            response.setStatus(HttpServletResponse.SC_OK);
55	            response.setContentType("application/json");
56	            response.getOutputStream().write(original);
57	            return;
58	        }
59	        ContentCachingResponseWrapper captured = new ContentCachingResponseWrapper(response);
60	        chain.doFilter(request, captured);
61	        if (captured.getStatus() == HttpServletResponse.SC_CREATED) {
62	            responsesByKey.put(key, captured.getContentAsByteArray());
63	        }
64	        captured.copyBodyToResponse();
65	    }
66	}
