58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
106	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        if (!Postcode.isValidForCity(owner.getCity(), owner.getPostcode())) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        if (DisposableEmail.isBlocked(owner.getEmail())) {
118	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
119	        }
120	        DailyOwnerLimitException.rejectIfAtLimit(this.clinicService.findAllOwners());
121	        boolean bulkSignupWarning = BulkSignup.isWarning(this.clinicService.findAllOwners());
122	        CityAtCapacityException.rejectIfAtCapacity(owner.getCity(), this.clinicService.findAllOwners());
123	        owner.setCapacityWarning(CityAtCapacityException.isApproachingCapacity(owner.getCity(), this.clinicService.findAllOwners()));
124	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
125	        IdentityKey.rejectIfDuplicate(owner, this.clinicService.findAllOwners());
126	        owner.setMemberId(MemberId.assign(owner, this.clinicService.findAllOwners()));
127	        owner.setNamesakeCount(Namesakes.count(owner, this.clinicService.findAllOwners()));
128	        owner.setHouseholdGold(org.springframework.samples.petclinic.util.GoldTier.qualifies(owner, this.clinicService.findAllOwners()));
129	        PossibleDuplicate.assign(owner, sharesHousehold, this.clinicService.findAllOwners());
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        ownerDto.setMembershipLevel(org.springframework.samples.petclinic.util.LevelCeiling.cap(ownerDto.getMembershipLevel(), owner, this.clinicService.findAllOwners()));
133	        org.slf4j.LoggerFactory.getLogger("AUDIT").info("owner id={} memberId={} registrationDate={} membershipLevel={}", owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
134	        org.springframework.samples.petclinic.util.OwnerCreatedEvent.emit(owner, ownerDto.getMembershipLevel());
135	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
136	        headers.setLocation(UriComponentsBuilder.newInstance()
137	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
138	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
144	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
145	        if (currentOwner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        currentOwner.setAddress(ownerFieldsDto.getAddress());
149	        currentOwner.setCity(ownerFieldsDto.getCity());
150	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
151	        currentOwner.setLastName(ownerFieldsDto.getLastName());
152	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
153	        this.clinicService.saveOwner(currentOwner);
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Transactional
159	    @Override
160	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        owner.setDeleted(true);
166	        this.clinicService.saveOwner(owner);
167	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Pet pet = petMapper.toPet(petFieldsDto);
179	        owner.setId(ownerId);
180	        pet.setOwner(owner);
181	        pet.getType().setName(null);
182	        this.clinicService.savePet(pet);
183	        PetDto petDto = petMapper.toPetDto(pet);
184	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
185	            .buildAndExpand(pet.getId()).toUri());
186	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner != null) {
194	            Pet currentPet = this.clinicService.findPetById(petId);
195	            if (currentPet != null) {
196	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
197	                currentPet.setName(petFieldsDto.getName());
198	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
199	                this.clinicService.savePet(currentPet);
200	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	            }
202	        }
203	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
209	        HttpHeaders headers = new HttpHeaders();
210	        Visit visit = visitMapper.toVisit(visitFieldsDto);
211	        Pet pet = new Pet();
212	        pet.setId(petId);
213	        visit.setPet(pet);
214	        this.clinicService.saveVisit(visit);
215	        VisitDto visitDto = visitMapper.toVisitDto(visit);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
217	            .buildAndExpand(visit.getId()).toUri());
218	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
219	    }
220	
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner != null) {
227	            Pet pet = owner.getPet(petId);
228	            if (pet != null) {
229	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
230	            }
231	        }
