6	/**
7	 * Canonicalizes a postal address so it is stored and compared in one consistent form:
8	 * surrounding whitespace is trimmed, internal whitespace runs collapse to a single space,
9	 * letters are upper-cased, and common abbreviations are expanded to their full words.
10	 */
11	public final class AddressNormalizer {
12	
13	    private static final Map<String, String> ABBREVIATIONS =
14	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
15	
16	    private AddressNormalizer() {
17	    }
18	
19	    /** Normalize {@code address}, or return it unchanged when {@code null}. */
20	    public static String normalize(String address) {
21	        if (address == null) {
22	            return null;
23	        }
24	        StringBuilder sb = new StringBuilder(address.length());
25	        for (String word : address.trim().toUpperCase(Locale.ROOT).split("\\s+")) {
26	            if (word.isEmpty()) {
27	                continue;
28	            }
29	            if (sb.length() > 0) {
30	                sb.append(' ');
31	            }
32	            sb.append(ABBREVIATIONS.getOrDefault(word, word));
33	        }
34	        return sb.toString();
35	    }
36	}
