17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Collection;
23	import java.util.Locale;
24	
25	import org.springframework.samples.petclinic.model.Owner;
26	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
27	
28	/**
29	 * Derives an owner's {@code identityKey}: the SHA-256 hex of
30	 * {@code normalizedTelephone|lowerEmail|soundex(lastName)}. All duplicate detection is
31	 * consolidated here: two owners are the same registration only when their identity keys are
32	 * equal, and a new owner is rejected only on a full match.
33	 */
34	public final class IdentityKey {
35	
36	    private IdentityKey() {
37	    }
38	
39	    /**
40	     * The lower-case SHA-256 hex over
41	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
42	     */
43	    public static String of(Owner owner) {
44	        String raw = CustomerCode.VERSION_TAG + "|" + telephone(owner.getTelephone()) + "|" + email(owner.getEmail())
45	                + "|" + Soundex.of(owner.getLastName());
46	        return sha256Hex(raw);
47	    }
48	
49	    private static String sha256Hex(String value) {
50	        try {
51	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
52	            StringBuilder sb = new StringBuilder(64);
53	            for (byte b : digest) {
54	                sb.append(String.format("%02x", b));
55	            }
56	            return sb.toString();
57	        }
58	        catch (NoSuchAlgorithmException e) {
59	            throw new IllegalStateException(e);
60	        }
61	    }
62	
63	    /** Reject with 409 when {@code candidate}'s whole identity key equals an existing owner's. */
64	    public static void rejectIfDuplicate(Owner candidate, Collection<Owner> existingOwners) {
65	        String key = of(candidate);
66	        for (Owner owner : existingOwners) {
67	            if (owner.isDeleted()) {
68	                continue;
69	            }
70	            if (key.equals(of(owner))) {
71	                throw new DuplicateTelephoneException(key);
72	            }
73	        }
74	    }
75	
76	    /** Digits only, so equality ignores telephone formatting differences. */
77	    private static String telephone(String telephone) {
78	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
79	    }
80	
81	    /** Lower-cased and trimmed, so equality ignores case; blank/absent emails compare equal. */
82	    private static String email(String email) {
83	        return email == null ? "" : email.trim().toLowerCase(Locale.ROOT);
84	    }
85	}
