2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Soft duplicate detection. A new owner that is not a hard duplicate but whose
9	 * {@code soundex(lastName)} and postcode match an existing owner (so only their differing
10	 * identity keys keep them apart) is a <em>possible</em> duplicate; the matching owner's id is
11	 * recorded on the candidate.
12	 */
13	public final class PossibleDuplicate {
14	
15	    private PossibleDuplicate() {
16	    }
17	
18	    /** Record on {@code candidate} whether it possibly duplicates an existing owner (matching
19	     *  {@code soundex(lastName)} and postcode but a different identity key) and, if so, that
20	     *  owner's id. A declared household member ({@code sharesHousehold}) is never a suspected
21	     *  duplicate. */
22	    public static void assign(Owner candidate, boolean sharesHousehold, Collection<Owner> existing) {
23	        Integer match = sharesHousehold ? null : matchId(candidate, existing);
24	        candidate.setPossibleDuplicate(match != null);
25	        candidate.setPossibleDuplicateOf(match);
26	    }
27	
28	    private static Integer matchId(Owner candidate, Collection<Owner> existing) {
29	        String key = IdentityKey.of(candidate);
30	        String soundex = Soundex.of(candidate.getLastName());
31	        for (Owner other : existing) {
32	            if (candidate.getPostcode() != null
33	                && candidate.getPostcode().equals(other.getPostcode())
34	                && soundex.equals(Soundex.of(other.getLastName()))
35	                && !key.equals(IdentityKey.of(other))) {
36	                return other.getId();
37	            }
38	        }
39	        return null;
40	    }
41	}
