18	
19	import java.util.Collection;
20	import java.util.Locale;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	
24	/**
25	 * Signals that a new owner's city already holds the maximum number of owners.
26	 * Mapped to HTTP 409 Conflict by {@link ExceptionControllerAdvice}.
27	 */
28	public class CityAtCapacityException extends RuntimeException {
29	
30	    /** Maximum owners allowed per city; the next owner in a full city is rejected. */
31	    private static final int CITY_CAPACITY = 50;
32	
33	    /** At or above this count (but below capacity) a city is flagged as approaching its limit. */
34	    private static final int CITY_WARNING_THRESHOLD = 40;
35	
36	    public CityAtCapacityException(String city) {
37	        super("City already at capacity: " + city);
38	    }
39	
40	    /** Canonicalize a city so comparison ignores case and collapses whitespace runs. */
41	    private static String normalize(String value) {
42	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
43	    }
44	
45	    /**
46	     * Throw if {@code existingOwners} already contains {@value #CITY_CAPACITY} or more owners
47	     * whose normalized city matches {@code city}.
48	     */
49	    public static void rejectIfAtCapacity(String city, Collection<Owner> existingOwners) {
50	        String candidate = normalize(city);
51	        long count = existingOwners.stream()
52	            .filter(owner -> candidate.equals(normalize(owner.getCity())))
53	            .count();
54	        if (count >= CITY_CAPACITY) {
55	            throw new CityAtCapacityException(city);
56	        }
57	    }
58	
59	    /**
60	     * Whether {@code city} already holds between {@value #CITY_WARNING_THRESHOLD} and
61	     * {@code CITY_CAPACITY - 1} owners, i.e. it is approaching but not yet at capacity.
62	     */
63	    public static boolean isApproachingCapacity(String city, Collection<Owner> existingOwners) {
64	        String candidate = normalize(city);
65	        long count = existingOwners.stream()
66	            .filter(owner -> candidate.equals(normalize(owner.getCity())))
67	            .count();
68	        return count >= CITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
69	    }
70	}
