5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Caps a new owner's membership level at one above the highest level currently held
9	 * by any other member of their household (owners sharing the same {@link Household}
10	 * id). With no existing household member, no ceiling applies.
11	 */
12	public final class LevelCeiling {
13	
14	    private LevelCeiling() {
15	    }
16	
17	    /**
18	     * {@code level} reduced to at most one above the maximum membership level among
19	     * {@code owner}'s existing household members in {@code allOwners} (excluding the
20	     * owner itself and soft-deleted records). Returns {@code level} unchanged when
21	     * the household has no other member.
22	     */
23	    public static int cap(int level, Owner owner, Collection<Owner> allOwners) {
24	        String household = Household.idFor(owner);
25	        int max = -1;
26	        for (Owner other : allOwners) {
27	            boolean self = other.getId() != null && other.getId().equals(owner.getId());
28	            if (self || other.isDeleted() || !household.equals(Household.idFor(other))) {
29	                continue;
30	            }
31	            max = Math.max(max, Membership.level(Membership.points(other)));
32	        }
33	        return max < 0 ? level : Math.min(level, max + 1);
34	    }
35	}
