6	
7	/**
8	 * Rolls a date forward onto a business day: weekends and listed public holidays
9	 * advance to the next non-holiday weekday, while an ordinary weekday is returned
10	 * unchanged.
11	 */
12	public final class BusinessDay {
13	
14	    /** Fixed public holidays that the roll skips over. */
15	    private static final Set<LocalDate> HOLIDAYS = Set.of(
16	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
17	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
18	            LocalDate.parse("2026-12-28"));
19	
20	    private BusinessDay() {
21	    }
22	
23	    private static boolean isBusinessDay(LocalDate date) {
24	        DayOfWeek day = date.getDayOfWeek();
25	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
26	    }
27	
28	    /** {@code date} unchanged when it is a business day, otherwise the next one. */
29	    public static LocalDate rollForward(LocalDate date) {
30	        while (!isBusinessDay(date)) {
31	            date = date.plusDays(1);
32	        }
33	        return date;
34	    }
35	}
